"use client";

import { useCart } from "@/app/store/cart";
import { X, Trash2, ShoppingBag, ChevronRight, Info } from "lucide-react";

export default function CartModal({ onClose }: { onClose: () => void }) {
  const { items, clearCart } = useCart();

  const total = items.reduce((sum, i) => sum + i.price * i.qty, 0);

  return (
    <div className="fixed inset-0 z-50">
      {/* Backdrop with blur */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      />

      {/* Cart Sheet */}
      <div className="absolute bottom-0 left-0 right-0 bg-white rounded-t-3xl shadow-2xl max-h-[90vh] flex flex-col animate-slide-up">
        {/* Header */}
        <div className="sticky top-0 bg-white border-b border-gray-100 rounded-t-3xl p-6 pb-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-emerald-50 rounded-lg">
                <ShoppingBag className="w-5 h-5 text-emerald-600" />
              </div>
              <div>
                <h2 className="font-bold text-xl text-gray-900">Your Cart</h2>
                <p className="text-sm text-gray-500">
                  {items.length} {items.length === 1 ? 'item' : 'items'}
                </p>
              </div>
            </div>
            <button
              onClick={onClose}
              className="p-2 hover:bg-gray-100 rounded-full transition-colors"
              aria-label="Close cart"
            >
              <X className="w-5 h-5 text-gray-500" />
            </button>
          </div>
        </div>

        {/* Cart Items */}
        <div className="flex-1 overflow-y-auto px-6 py-4">
          {items.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 text-center">
              <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mb-4">
                <ShoppingBag className="w-8 h-8 text-gray-400" />
              </div>
              <p className="text-gray-900 font-medium text-lg mb-2">Your cart is empty</p>
              <p className="text-gray-500 text-sm">Add items to get started</p>
            </div>
          ) : (
            <div className="space-y-4">
              {items.map((item) => (
                <div
                  key={`${item.productId}-${item.sizeLabel}`}
                  className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50 border border-gray-100"
                >
                  {/* Veg/Non-veg indicator */}
                  <div className="flex-shrink-0 mt-1">
                    <div
                      className={`w-3 h-3 rounded-full border-2 ${
                        item.veg
                          ? "border-emerald-500 bg-emerald-100"
                          : "border-rose-500 bg-rose-100"
                      }`}
                    />
                  </div>

                  {/* Item details */}
                  <div className="flex-1 min-w-0">
                    <div className="flex justify-between items-start mb-1">
                      <h3 className="font-semibold text-gray-900 truncate">
                        {item.name}
                      </h3>
                      <p className="font-bold text-gray-900 ml-2">
                        ₹{item.price * item.qty}
                      </p>
                    </div>
                    
                    <div className="flex items-center justify-between mt-2">
                      <div className="flex items-center gap-3">
                        <span className="px-3 py-1 bg-white border border-gray-200 rounded-full text-sm text-gray-600">
                          {item.sizeLabel}
                        </span>
                        <span className="text-sm text-gray-500">
                          × {item.qty}
                        </span>
                      </div>
                      <p className="text-sm font-medium text-gray-700">
                        ₹{item.price} each
                      </p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Footer */}
        {items.length > 0 && (
          <div className="sticky bottom-0 bg-white border-t border-gray-100 p-6 space-y-5">
            {/* Total */}
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-500">Total amount</p>
                <p className="text-2xl font-bold text-gray-900">₹{total}</p>
              </div>
              <div className="text-right">
                <p className="text-xs text-gray-500 mb-1">Inclusive of all taxes</p>
                <div className="inline-flex items-center gap-1 px-3 py-1 bg-emerald-50 text-emerald-700 rounded-full text-sm">
                  <Info className="w-3 h-3" />
                  <span>Free delivery</span>
                </div>
              </div>
            </div>

            {/* Info Banner */}
            <div className="bg-blue-50 border border-blue-100 rounded-xl p-4">
              <div className="flex items-start gap-3">
                <Info className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" />
                <p className="text-sm text-blue-800">
                  Show this cart to the waiter for a seamless ordering experience
                </p>
              </div>
            </div>

            {/* Action Buttons */}
            <div className="flex gap-3">
              <button
                onClick={clearCart}
                className="flex-1 flex items-center justify-center gap-2 px-6 py-4 border-2 border-gray-200 text-gray-700 font-semibold rounded-xl hover:bg-gray-50 active:bg-gray-100 transition-colors"
              >
                <Trash2 className="w-5 h-5" />
                Clear All
              </button>
              <button
                onClick={() => {
                  // Handle checkout logic here
                  alert("Proceeding to checkout!");
                }}
                className="flex-1 flex items-center justify-center gap-2 px-6 py-4 bg-gradient-to-r from-emerald-500 to-emerald-600 text-white font-semibold rounded-xl shadow-lg shadow-emerald-500/25 hover:shadow-xl hover:shadow-emerald-500/30 active:scale-[0.98] transition-all"
              >
                Order Now
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>

            <p className="text-center text-xs text-gray-500 pt-2">
              You can modify your order until the waiter confirms
            </p>
          </div>
        )}
      </div>
    </div>
  );
}